import { saveVendorBankAccountSchema, type SaveVendorBankAccount } from "@amiyo/contracts";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import type { User } from "firebase/auth";
import { router } from "expo-router";
import { useEffect, useRef, useState } from "react";
import { ActivityIndicator, Pressable, StyleSheet, Text, TextInput, useWindowDimensions, View } from "react-native";
import { ModuleCard } from "../../ui/ModuleCard";
import { Screen } from "../../ui/Screen";
import { colors, radius, spacing } from "../../ui/tokens";
import { useCurrentUser } from "../auth/use-current-user";
import { getVendorWorkspace, saveVendorBankAccount } from "./vendor.api";

const providers = ["BANK", "BKASH", "NAGAD", "ROCKET"] as const;
type Provider = (typeof providers)[number];
const emptyForm = { provider: "BANK" as Provider, accountName: "", accountNumber: "", confirmAccountNumber: "" };

export function VendorPayoutSettingsScreen() {
  const user = useCurrentUser();
  const activeUid = useRef(user?.uid);
  activeUid.current = user?.uid;
  const compact = useWindowDimensions().width < 620;
  const queryClient = useQueryClient();
  const [form, setForm] = useState(emptyForm);
  const workspaceKey = ["vendor", "workspace", user?.uid] as const;
  const workspace = useQuery({ queryKey: workspaceKey, queryFn: () => getVendorWorkspace(user!), enabled: Boolean(user), retry: false });
  const accounts = workspace.data?.bankAccounts ?? [];
  const verifiedCount = accounts.filter((account) => account.verifiedAt).length;
  const defaultAccount = accounts.find((account) => account.isDefault) ?? accounts[0];
  useEffect(() => { setForm(emptyForm); }, [user?.uid]);
  const parsed = saveVendorBankAccountSchema.safeParse({ provider: form.provider, accountName: form.accountName, accountNumber: form.accountNumber, isDefault: true });
  const matches = form.accountNumber.length > 0 && form.accountNumber === form.confirmAccountNumber;
  const save = useMutation({
    retry: false,
    mutationFn: ({ owner, payload }: { owner: User; payload: SaveVendorBankAccount }) => saveVendorBankAccount(owner, payload),
    onSuccess: async (_data, variables) => {
      if (activeUid.current !== variables.owner.uid) return;
      setForm(emptyForm);
      await queryClient.invalidateQueries({ queryKey: ["vendor", "workspace", variables.owner.uid] });
    }
  });
  return <Screen eyebrow="SELLER CENTER" title="Bank & payout settings" description="Manage verified payout destinations for seller withdrawals.">
    <View style={[styles.securityHero, compact && styles.securityHeroCompact]}><View style={styles.securityCopy}><Text style={styles.securityEyebrow}>PAYOUT READINESS</Text><Text accessibilityRole="header" style={styles.securityTitle}>{verifiedCount ? "Finance setup protected" : accounts.length ? "Verification pending" : "Add a payout destination"}</Text><Text style={styles.securityText}>Account numbers are encrypted at rest, masked after saving and reviewed before settlement.</Text><View style={styles.securityTrust}><Ionicons color={colors.accent} name="shield-checkmark" size={18} /><Text style={styles.securityTrustText}>Only use an account owned by you or your registered business.</Text></View></View><View style={[styles.securityMetrics, compact && styles.securityMetricsCompact]}><FinanceMetric label="Saved" value={String(accounts.length)} /><FinanceMetric label="Verified" value={String(verifiedCount)} /><FinanceMetric label="Default" value={defaultAccount?.provider ?? "Not set"} /></View></View>
    <ModuleCard title="Saved payout accounts" meta={`${accounts.length} secure destination${accounts.length === 1 ? "" : "s"}`}>{workspace.isLoading ? <ActivityIndicator color={colors.primary} /> : null}{workspace.error ? <Text accessibilityRole="alert" style={styles.error}>{workspace.error.message}</Text> : null}{accounts.map((account) => <View key={account.id} style={[styles.account, compact && compactStyles.account]}><View style={styles.providerIcon}><Ionicons color={colors.primary} name={account.provider === "BANK" ? "business-outline" : "phone-portrait-outline"} size={19} /></View><View style={compactStyles.accountCopy}><Text numberOfLines={1} style={styles.accountName}>{account.provider} · {account.accountNumberMasked}</Text><Text numberOfLines={1} style={styles.muted}>{account.accountName}</Text></View><View style={[styles.accountBadges, compact && styles.accountBadgesCompact]}>{account.isDefault ? <Text style={[styles.badge, styles.default]}>Default</Text> : null}<Text style={[styles.badge, account.verifiedAt ? styles.verified : styles.pending]}>{account.verifiedAt ? "Verified" : "Pending review"}</Text></View></View>)}{!workspace.isLoading && !accounts.length ? <View style={styles.empty}><Ionicons color={colors.primary} name="wallet-outline" size={34} /><Text style={styles.emptyTitle}>No payout account saved</Text><Text style={styles.muted}>Add a bank or MFS destination below to prepare for seller settlements.</Text></View> : null}</ModuleCard>
    <ModuleCard title="Add payout account" meta="The newest account becomes your default."><Text style={styles.label}>Payout method</Text><View style={styles.providers}>{providers.map((provider) => <Pressable accessibilityRole="button" key={provider} onPress={() => setForm((current) => ({ ...current, provider }))} style={[styles.chip, form.provider === provider && styles.activeChip]}><Text style={[styles.chipText, form.provider === provider && styles.activeChipText]}>{provider === "BANK" ? "Bank transfer" : provider}</Text></Pressable>)}</View><Field autoComplete="name" label={form.provider === "BANK" ? "Bank account name" : "Account holder name"} onChangeText={(accountName) => setForm((current) => ({ ...current, accountName }))} value={form.accountName} /><Field autoComplete="off" inputMode="numeric" label={form.provider === "BANK" ? "Bank account number" : `${form.provider} number`} onChangeText={(accountNumber) => setForm((current) => ({ ...current, accountNumber }))} secureTextEntry value={form.accountNumber} /><Field autoComplete="off" inputMode="numeric" label="Confirm account number" onChangeText={(confirmAccountNumber) => setForm((current) => ({ ...current, confirmAccountNumber }))} secureTextEntry value={form.confirmAccountNumber} />{form.confirmAccountNumber && !matches ? <Text accessibilityRole="alert" style={styles.error}>Account numbers do not match.</Text> : null}{!parsed.success && (form.accountName || form.accountNumber) ? <Text style={styles.help}>Enter an account holder name and an account number between 8 and 40 characters.</Text> : null}<Pressable accessibilityRole="button" disabled={!user || !parsed.success || !matches || save.isPending} onPress={() => save.mutate({ owner: user!, payload: parsed.success ? parsed.data : { provider: "BANK", accountName: "", accountNumber: "", isDefault: true } })} style={[styles.button, (!user || !parsed.success || !matches || save.isPending) && styles.disabled]}>{save.isPending ? <ActivityIndicator color={colors.surface} /> : <Text style={styles.buttonText}>Save payout account</Text>}</Pressable>{save.error ? <Text accessibilityRole="alert" style={styles.error}>{save.error.message}</Text> : null}</ModuleCard>
    {save.isSuccess || Boolean(workspace.data?.bankAccounts.length) ? <View style={styles.finishCard}><View style={styles.finishIcon}><Text style={styles.finishIconText}>✓</Text></View><View style={styles.finishCopy}><Text style={styles.finishTitle}>Seller setup is ready</Text><Text style={styles.muted}>Open your dashboard to add products, review orders and track approval.</Text></View><Pressable accessibilityRole="button" onPress={() => router.replace("/vendor")} style={[styles.finishButton, compact && styles.finishButtonCompact]}><Text style={styles.buttonText}>Open seller dashboard</Text></Pressable></View> : null}
  </Screen>;
}

function Field({ label, ...props }: React.ComponentProps<typeof TextInput> & { label: string }) { return <View style={styles.field}><Text style={styles.label}>{label}</Text><TextInput accessibilityLabel={label} placeholderTextColor={colors.muted} style={styles.input} {...props} /></View>; }
function FinanceMetric({ label, value }: { label: string; value: string }) { return <View style={styles.securityMetric}><Text numberOfLines={1} style={styles.securityMetricValue}>{value}</Text><Text style={styles.securityMetricLabel}>{label}</Text></View>; }
const compactStyles = StyleSheet.create({ account: { alignItems: "flex-start", gap: spacing.sm }, accountCopy: { flex: 1, minWidth: 0 } });
const styles = StyleSheet.create({ securityHero: { alignItems: "stretch", backgroundColor: colors.navy, borderRadius: radius.xl, boxShadow: "0 12px 30px rgba(11,31,58,.12)", flexDirection: "row", gap: spacing.xl, padding: spacing.xl }, securityHeroCompact: { flexDirection: "column", gap: spacing.lg, padding: spacing.lg }, securityCopy: { flex: 1, minWidth: 0 }, securityEyebrow: { color: "#D9E6A7", fontSize: 9, fontWeight: "700", letterSpacing: 1 }, securityTitle: { color: colors.surface, fontSize: 24, fontWeight: "700", marginTop: 6 }, securityText: { color: "rgba(250,247,240,.74)", fontSize: 11, lineHeight: 18, marginTop: spacing.sm }, securityTrust: { alignItems: "center", flexDirection: "row", gap: 7, marginTop: spacing.md }, securityTrustText: { color: "#D9E6A7", flex: 1, fontSize: 10, fontWeight: "600" }, securityMetrics: { flexDirection: "row", gap: spacing.sm, minWidth: 330 }, securityMetricsCompact: { minWidth: 0, width: "100%" }, securityMetric: { alignItems: "center", backgroundColor: "rgba(255,255,255,.09)", borderRadius: radius.lg, flex: 1, justifyContent: "center", minHeight: 88, minWidth: 0, padding: spacing.sm }, securityMetricValue: { color: colors.surface, fontSize: 17, fontWeight: "700", maxWidth: "100%" }, securityMetricLabel: { color: "rgba(250,247,240,.65)", fontSize: 9, marginTop: 4 }, muted: { color: colors.muted, fontSize: 12 }, account: { alignItems: "center", borderBottomColor: colors.border, borderBottomWidth: 1, flexDirection: "row", gap: spacing.sm, paddingVertical: spacing.md }, providerIcon: { alignItems: "center", backgroundColor: colors.primarySoft, borderRadius: radius.md, height: 40, justifyContent: "center", width: 40 }, accountName: { color: colors.text, fontWeight: "700" }, accountBadges: { alignItems: "center", flexDirection: "row", flexWrap: "wrap", gap: 5, justifyContent: "flex-end" }, accountBadgesCompact: { justifyContent: "flex-start", width: "100%" }, badge: { borderRadius: radius.pill, fontSize: 9, fontWeight: "700", overflow: "hidden", paddingHorizontal: 8, paddingVertical: 5 }, verified: { backgroundColor: colors.accentSoft, color: colors.success }, pending: { backgroundColor: colors.primarySoft, color: colors.primary }, default: { backgroundColor: colors.navy, color: colors.surface }, empty: { alignItems: "center", gap: spacing.sm, padding: spacing.xl }, emptyTitle: { color: colors.text, fontSize: 16, fontWeight: "700" }, providers: { flexDirection: "row", flexWrap: "wrap", gap: spacing.sm }, chip: { borderColor: colors.border, borderRadius: radius.pill, borderWidth: 1, paddingHorizontal: 12, paddingVertical: 8 }, activeChip: { backgroundColor: colors.primary, borderColor: colors.primary }, chipText: { color: colors.text, fontSize: 11, fontWeight: "600" }, activeChipText: { color: colors.surface }, field: { gap: 5 }, label: { color: colors.text, fontSize: 12, fontWeight: "600" }, input: { backgroundColor: colors.surface, borderColor: colors.border, borderRadius: radius.md, borderWidth: 1, color: colors.text, minHeight: 46, paddingHorizontal: 12 }, button: { alignItems: "center", backgroundColor: colors.primary, borderRadius: radius.md, justifyContent: "center", minHeight: 46 }, disabled: { opacity: .45 }, buttonText: { color: colors.surface, fontWeight: "700" }, finishCard: { alignItems: "center", backgroundColor: colors.accentSoft, borderRadius: radius.xl, flexDirection: "row", flexWrap: "wrap", gap: spacing.md, padding: spacing.lg }, finishIcon: { alignItems: "center", backgroundColor: colors.accent, borderRadius: radius.pill, height: 42, justifyContent: "center", width: 42 }, finishIconText: { color: colors.surface, fontSize: 20, fontWeight: "700" }, finishCopy: { flex: 1, minWidth: 200 }, finishTitle: { color: colors.text, fontSize: 16, fontWeight: "700", marginBottom: 3 }, finishButton: { alignItems: "center", backgroundColor: colors.primary, borderRadius: radius.md, justifyContent: "center", minHeight: 44, paddingHorizontal: spacing.md }, finishButtonCompact: { width: "100%" }, error: { color: colors.danger, fontSize: 12 }, help: { color: colors.muted, fontSize: 11 } });
